import { useState, useEffect } from 'react'
import {
  BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell,
  LineChart, Line, Legend, CartesianGrid
} from 'recharts'
import { motion } from 'framer-motion'
import { GoogleGenerativeAI } from '@google/generative-ai'
import { useUser } from '../context/UserContext'
import { useCalorieData } from '../hooks/useCalorieData'
import BottomNav from '../components/BottomNav'
import styles from './Progress.module.css'

const genAI = new GoogleGenerativeAI(import.meta.env.VITE_GEMINI_API_KEY)

function getWeekKey() {
  const d = new Date()
  const jan1 = new Date(d.getFullYear(), 0, 1)
  const week = Math.ceil(((d - jan1) / 86400000 + jan1.getDay() + 1) / 7)
  return `${d.getFullYear()}-W${week}`
}

export default function Progress() {
  const { weeklyReport, saveWeeklyReport, calorieGoal, dietaryPreference, fitnessGoal } = useUser()
  const { weekData, bestDay, worstDay } = useCalorieData()
  const [reportLoading, setReportLoading] = useState(false)
  const weekKey = getWeekKey()
  const report = weeklyReport[weekKey]

  const isSunday = new Date().getDay() === 0

  async function generateReport() {
    setReportLoading(true)
    try {
      if (!import.meta.env.VITE_GEMINI_API_KEY) {
        saveWeeklyReport(weekKey, getMockReport())
        return
      }
      const summary = weekData.map(d => `${d.label}: ${d.kcal} kcal, P${d.protein}g C${d.carbs}g F${d.fat}g`).join('\n')
      const reportModel = genAI.getGenerativeModel({
        model: 'gemini-2.5-flash',
        systemInstruction: 'You are Petal, a warm wellness coach. Write encouraging weekly nutrition reports (3-4 sentences). Include best day, macro gaps, and a next-week goal. Use one flower/nature metaphor. No markdown.',
      })
      const reportResult = await reportModel.generateContent(
        `Diet: ${dietaryPreference}, Goal: ${fitnessGoal}, Daily target: ${calorieGoal} kcal\n${summary}`
      )
      saveWeeklyReport(weekKey, {
        summary: reportResult.response.text(),
        bestDay: bestDay?.label || '—',
        worstDay: worstDay?.label || '—',
        generatedAt: new Date().toISOString()
      })
    } catch (e) {
      saveWeeklyReport(weekKey, getMockReport())
    } finally {
      setReportLoading(false)
    }
  }

  function getMockReport() {
    return {
      summary: `You've been blooming beautifully this week! Your ${bestDay?.label || 'best day'} was a highlight — great calorie balance and macro distribution. Watch your protein intake mid-week; try adding lentils or paneer to lunch. For next week, aim to hit 80% of your protein goal every day — your body will thank you with renewed energy.`,
      bestDay: bestDay?.label || '—',
      worstDay: worstDay?.label || '—',
      generatedAt: new Date().toISOString()
    }
  }

  const CustomTooltip = ({ active, payload, label }) => {
    if (active && payload?.length) {
      return (
        <div className={styles.tooltip}>
          <p className={styles.tooltipLabel}>{label}</p>
          <p style={{ color: 'var(--rose-dark)' }}>{payload[0].value} kcal</p>
        </div>
      )
    }
    return null
  }

  return (
    <div className={`page ${styles.progress}`}>
      <div className={styles.header}>
        <h1 className={styles.title}>Weekly Progress</h1>
        <p className={styles.sub}>Your bloom journey this week</p>
      </div>

      {/* Calorie bar chart */}
      <div className={styles.card}>
        <h3 className={styles.cardTitle}>Daily Calories</h3>
        <ResponsiveContainer width="100%" height={180}>
          <BarChart data={weekData} margin={{ top: 4, right: 0, left: -20, bottom: 0 }}>
            <XAxis dataKey="label" tick={{ fontSize: 11, fill: '#806068' }} axisLine={false} tickLine={false} />
            <YAxis tick={{ fontSize: 10, fill: '#806068' }} axisLine={false} tickLine={false} />
            <Tooltip content={<CustomTooltip />} />
            <Bar dataKey="kcal" radius={[6, 6, 0, 0]}>
              {weekData.map((d, i) => (
                <Cell key={i} fill={d.kcal <= calorieGoal ? '#f9c8d8' : '#d4607a'} />
              ))}
            </Bar>
          </BarChart>
        </ResponsiveContainer>
      </div>

      {/* Macro trend line chart */}
      <div className={styles.card}>
        <h3 className={styles.cardTitle}>Macro Trends</h3>
        <ResponsiveContainer width="100%" height={180}>
          <LineChart data={weekData} margin={{ top: 4, right: 8, left: -20, bottom: 0 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="#ecdee8" />
            <XAxis dataKey="label" tick={{ fontSize: 11, fill: '#806068' }} axisLine={false} tickLine={false} />
            <YAxis tick={{ fontSize: 10, fill: '#806068' }} axisLine={false} tickLine={false} />
            <Tooltip />
            <Legend wrapperStyle={{ fontSize: 11 }} />
            <Line type="monotone" dataKey="protein" stroke="#d4607a" strokeWidth={2} dot={false} name="Protein" />
            <Line type="monotone" dataKey="carbs"   stroke="#9060c8" strokeWidth={2} dot={false} name="Carbs" />
            <Line type="monotone" dataKey="fat"     stroke="#d07030" strokeWidth={2} dot={false} name="Fat" />
          </LineChart>
        </ResponsiveContainer>
      </div>

      {/* Best / worst day */}
      <div className={styles.dayCards}>
        <div className={styles.dayCard} style={{ background: 'var(--surface-matcha)', borderColor: 'var(--matcha)' }}>
          <span className={styles.dayEmoji}>✨</span>
          <span className={styles.dayLabel}>Best day</span>
          <span className={styles.dayValue}>{bestDay?.label || '—'}</span>
          {bestDay && <span className={styles.dayKcal}>{bestDay.kcal} kcal</span>}
        </div>
        <div className={styles.dayCard} style={{ background: 'var(--surface-rose)', borderColor: 'var(--rose)' }}>
          <span className={styles.dayEmoji}>🌿</span>
          <span className={styles.dayLabel}>Most calories</span>
          <span className={styles.dayValue}>{worstDay?.label || '—'}</span>
          {worstDay && <span className={styles.dayKcal}>{worstDay.kcal} kcal</span>}
        </div>
      </div>

      {/* Weekly AI Report */}
      <div className={styles.reportCard}>
        <h3 className={styles.cardTitle}>Weekly AI Report</h3>
        {report ? (
          <div>
            <p className={styles.reportText}>{report.summary}</p>
            <p className={styles.reportMeta}>Generated {new Date(report.generatedAt).toLocaleDateString()}</p>
          </div>
        ) : (
          <div className={styles.reportEmpty}>
            <p>{isSunday ? 'Generate your weekly bloom report!' : 'Available every Sunday — keep logging!'}</p>
            <button
              className={styles.reportBtn}
              onClick={generateReport}
              disabled={reportLoading}>
              {reportLoading ? 'Generating...' : 'Generate Report'}
            </button>
          </div>
        )}
      </div>

      <BottomNav />
    </div>
  )
}

import { useState, useCallback } from 'react'
import { GoogleGenerativeAI } from '@google/generative-ai'

const genAI = new GoogleGenerativeAI(import.meta.env.VITE_GEMINI_API_KEY)

export function useAiCoach() {
  const [tip, setTip] = useState('')
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState(null)

  const fetchTip = useCallback(async ({ totals, goals, preference, fitnessGoal }) => {
    if (!import.meta.env.VITE_GEMINI_API_KEY) {
      setTip(getLocalTip(totals, goals, preference))
      return
    }
    setLoading(true)
    setError(null)
    try {
      const dietLabel = preference === 'veg' ? 'vegetarian' : 'non-vegetarian'
      const coachModel = genAI.getGenerativeModel({
        model: 'gemini-2.5-flash',
        systemInstruction: 'You are Petal, a warm AI wellness coach for a calorie tracking app. Give ONE short (2-3 sentence), personalized, encouraging tip. Use one flower/nature metaphor. No markdown.',
      })
      const coachResult = await coachModel.generateContent(
        `Stats: ${totals.kcal}/${goals.kcal} kcal, P${totals.protein}g/${goals.protein}g, C${totals.carbs}g/${goals.carbs}g, F${totals.fat}g/${goals.fat}g. Diet: ${dietLabel}. Goal: ${fitnessGoal}. Only suggest ${dietLabel} foods.`
      )
      setTip(coachResult.response.text())
    } catch (e) {
      setError(e.message)
      setTip(getLocalTip(totals, goals, preference))
    } finally {
      setLoading(false)
    }
  }, [])

  return { tip, loading, error, fetchTip }
}

function getLocalTip(totals, goals, preference) {
  const remaining = (goals.kcal || 2000) - (totals.kcal || 0)
  if (remaining < 200) return preference === 'veg'
    ? 'You\'re blooming beautifully today! A light dal soup or fruit bowl would round off your day perfectly.'
    : 'You\'re almost at your goal! A light salad or lean protein snack would be a lovely finish.'
  if ((totals.protein || 0) < (goals.protein || 50) * 0.5) return preference === 'veg'
    ? 'Your petals need protein to flourish! Try adding paneer, lentils, or Greek yogurt to your next meal.'
    : 'Your body blooms with protein! Consider adding eggs, grilled chicken, or Greek yogurt to stay strong.'
  return preference === 'veg'
    ? 'You\'re nurturing yourself beautifully! Keep your meals colorful with veggies and whole grains.'
    : 'Great balance today! Keep nourishing yourself with whole foods and stay hydrated like a garden in morning light.'
}

import { createContext, useContext, useState, useEffect, useCallback } from 'react'

const UserContext = createContext(null)

const DEFAULT_STATE = {
  name: '',
  photo: null,
  calorieGoal: 2000,
  dietaryPreference: 'non-veg', // 'veg' | 'non-veg'
  fitnessGoal: 'maintain',      // 'lose' | 'maintain' | 'gain'
  waterGoal: 8,
  onboardingDone: false,
  diary: {},       // { 'YYYY-MM-DD': [{ id, name, kcal, protein, carbs, fat, mealTime, score, isVeg, mood, energy, timestamp }] }
  water: {},       // { 'YYYY-MM-DD': number }
  streak: 0,
  lastLogDate: null,
  milestones: [],  // [3, 7, 14, 30] days achieved
  weeklyReport: {},// { 'YYYY-WW': { summary, bestDay, worstDay, macroGaps, nextGoal } }
  notifications: true,
}

function today() {
  return new Date().toISOString().slice(0, 10)
}

export function UserProvider({ children }) {
  const [state, setState] = useState(() => {
    try {
      const saved = localStorage.getItem('calsnap_state')
      return saved ? { ...DEFAULT_STATE, ...JSON.parse(saved) } : DEFAULT_STATE
    } catch {
      return DEFAULT_STATE
    }
  })

  useEffect(() => {
    localStorage.setItem('calsnap_state', JSON.stringify(state))
  }, [state])

  const update = useCallback((patch) => {
    setState(prev => ({ ...prev, ...patch }))
  }, [])

  const completeOnboarding = useCallback((data) => {
    setState(prev => ({ ...prev, ...data, onboardingDone: true }))
  }, [])

  const addDiaryEntry = useCallback((entry) => {
    const date = today()
    setState(prev => {
      const dayEntries = prev.diary[date] || []
      const newEntry = { ...entry, id: Date.now(), timestamp: new Date().toISOString() }
      const newDiary = { ...prev.diary, [date]: [...dayEntries, newEntry] }

      let streak = prev.streak
      let lastLogDate = prev.lastLogDate
      const milestones = [...(prev.milestones || [])]

      if (lastLogDate !== date) {
        const yesterday = new Date()
        yesterday.setDate(yesterday.getDate() - 1)
        const yStr = yesterday.toISOString().slice(0, 10)
        streak = lastLogDate === yStr ? streak + 1 : 1
        lastLogDate = date
        ;[3, 7, 14, 30].forEach(m => {
          if (streak >= m && !milestones.includes(m)) milestones.push(m)
        })
      }

      return { ...prev, diary: newDiary, streak, lastLogDate, milestones }
    })
  }, [])

  const deleteDiaryEntry = useCallback((id) => {
    const date = today()
    setState(prev => {
      const dayEntries = (prev.diary[date] || []).filter(e => e.id !== id)
      return { ...prev, diary: { ...prev.diary, [date]: dayEntries } }
    })
  }, [])

  const logWater = useCallback((amount) => {
    const date = today()
    setState(prev => {
      const current = prev.water[date] || 0
      return { ...prev, water: { ...prev.water, [date]: Math.max(0, current + amount) } }
    })
  }, [])

  const saveWeeklyReport = useCallback((weekKey, report) => {
    setState(prev => ({
      ...prev,
      weeklyReport: { ...prev.weeklyReport, [weekKey]: report }
    }))
  }, [])

  const todayEntries = state.diary[today()] || []
  const todayWater = state.water[today()] || 0

  const todayTotals = todayEntries.reduce(
    (acc, e) => ({
      kcal: acc.kcal + (e.kcal || 0),
      protein: acc.protein + (e.protein || 0),
      carbs: acc.carbs + (e.carbs || 0),
      fat: acc.fat + (e.fat || 0),
    }),
    { kcal: 0, protein: 0, carbs: 0, fat: 0 }
  )

  const value = {
    ...state,
    update,
    completeOnboarding,
    addDiaryEntry,
    deleteDiaryEntry,
    logWater,
    saveWeeklyReport,
    todayEntries,
    todayWater,
    todayTotals,
    today: today(),
  }

  return <UserContext.Provider value={value}>{children}</UserContext.Provider>
}

export const useUser = () => {
  const ctx = useContext(UserContext)
  if (!ctx) throw new Error('useUser must be used inside UserProvider')
  return ctx
}

