*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #fdf6f2;
  --hero-gradient: linear-gradient(135deg, #fad4e0, #e4d8f8, #fae0c0);
  --surface-rose: #fad4e0;
  --surface-lavender: #e4d8f8;
  --surface-matcha: #d4ecc8;
  --surface-peach: #fae0c0;
  --rose: #f9c8d8;
  --rose-dark: #d4607a;
  --rose-text: #a0304a;
  --lavender: #ddd0f5;
  --lavender-dark: #9060c8;
  --lavender-text: #5030a0;
  --peach: #f8d8b8;
  --peach-dark: #d07030;
