.report {
  background: white;
  border: 1.5px solid #ecdee8;
  border-radius: var(--radius);
  overflow: hidden;
  margin-bottom: 0;
}

/* ── Header ── */
.reportHeader {
  background: linear-gradient(135deg, #fad4e0, #e4d8f8);
  padding: 20px 20px 16px;
  text-align: center;
  border-bottom: 1px solid #e8d4e0;
}
.appLogo {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: #a0304a;
  text-transform: uppercase;
  margin-bottom: 6px;
}
.reportTitle {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: 19px;
  font-style: italic;
  color: var(--text);
  margin-bottom: 4px;
}
.dateRange {
  font-size: 12px;
  color: var(--text-muted);
  letter-spacing: 0.02em;
}

/* ── Section ── */
.section {
  padding: 14px 16px;
  border-bottom: 1px solid #f5eff3;
}
.section:last-child {
  border-bottom: none;
}
.sectionPill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: 0.04em;
  padding: 4px 12px;
  border-radius: 999px;
  margin-bottom: 10px;
  text-transform: uppercase;
}

/* ── Overview ── */
.overviewText {
  font-size: 13.5px;
  line-height: 1.65;
  color: var(--text);
  margin-bottom: 12px;
}
.dayBadges {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}
.dayBadge {
  border: 1px solid;
  border-radius: var(--radius-sm);
  padding: 10px 8px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  text-align: center;
}
.dayBadgeIcon { font-size: 18px; margin-bottom: 2px; }
.dayBadgeLabel {
  font-size: 10px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.dayBadgeName {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: 15px;
  font-style: italic;
  color: var(--text);
}
.dayBadgeKcal { font-size: 11px; color: var(--text-muted); }

/* ── Chart ── */
.chartMeta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 6px;
}
.chartLabel {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.avgBadge {
  font-size: 11px;
  background: #fad4e0;
  color: #a0304a;
  padding: 3px 10px;
  border-radius: 999px;
  font-weight: 600;
}
.tooltip {
  background: white;
  border: 1.5px solid #f0a8b8;
  border-radius: var(--radius-sm);
  padding: 7px 11px;
  font-size: 12px;
}
.tooltipLabel { color: var(--text-muted); margin-bottom: 1px; }

/* ── Macro Table ── */
.macroTableWrap {
  margin-top: 12px;
  overflow-x: auto;
  border-radius: var(--radius-sm);
  border: 1px solid #ecdee8;
}
.macroTable {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
}
.macroTable th {
  padding: 7px 10px;
  background: #fdf0f4;
  color: var(--text-muted);
  font-weight: 600;
  text-align: center;
  border-bottom: 1px solid #ecdee8;
}
.macroTable th:first-child { text-align: left; }
.macroTable td {
  padding: 6px 10px;
  text-align: center;
  color: var(--text);
  border-bottom: 1px solid #f8f0f4;
}
.macroTable td:first-child { text-align: left; }
.macroTable tr:last-child td { border-bottom: none; }
.rowEven td { background: #fdf8fa; }
.dayCell { font-weight: 500; color: var(--text); }

/* ── Macro Summary Chips ── */
.macroRow {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 8px;
}
.macroChip {
  border: 1px solid;
  border-radius: var(--radius-sm);
  padding: 10px 6px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  text-align: center;
}
.macroChipLabel {
  font-size: 10px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.macroChipValue {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: 17px;
  font-weight: 700;
  font-style: italic;
}
.macroChipGoal { font-size: 10px; color: var(--text-muted); }
.macroChipStatus {
  font-size: 10px;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 999px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  margin-top: 2px;
}

/* ── Bullet Lists ── */
.bulletList {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 7px;
}
.bulletItem {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  font-size: 13.5px;
  line-height: 1.5;
  color: var(--text);
}
.bulletDot {
  flex-shrink: 0;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  margin-top: 6px;
}

/* ── Next Week Goal ── */
.goalText {
  font-size: 13.5px;
  line-height: 1.65;
  color: var(--text);
  background: #f0f8ec;
  border-left: 3px solid #68b868;
  padding: 10px 12px;
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
}

/* ── Footer ── */
.reportFooter {
  padding: 12px 16px;
  font-size: 11px;
  color: var(--text-muted);
  text-align: center;
  background: #fdf8fa;
  border-top: 1px solid #f0e8ec;
  letter-spacing: 0.02em;
}

/* ── Download Button ── */
.downloadBtn {
  display: block;
  width: 100%;
  margin-top: 14px;
  padding: 14px 20px;
  background: linear-gradient(135deg, #b090e0, #9060c8);
  color: white;
  border-radius: var(--radius);
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.02em;
  text-align: center;
  cursor: pointer;
  border: none;
  transition: opacity 0.2s, transform 0.1s;
}
.downloadBtn:hover:not(:disabled) {
  opacity: 0.92;
  transform: translateY(-1px);
}
.downloadBtn:active:not(:disabled) {
  transform: translateY(0);
}
.downloadBtn:disabled {
  opacity: 0.65;
  cursor: default;
}
.downloadBtn[data-state='done'] {
  background: linear-gradient(135deg, #68b868, #408040);
}

